def verify_constraints(m, S_m, T):
    # Constraint (a): Each element of T is an m-element subset of S_m
    for t in T:
        if len(t) != m:
            print(f"FAIL (a): Set has size {len(t)}, expected {m}")
            return False
        if not all(element in S_m for element in t):
            print(f"FAIL (a): Element outside S_m found in {t}")
            return False

    # Constraint (b): Each pair of elements of T shares at most one common element
    T_list = list(T)
    for i in range(len(T_list)):
        for j in range(i + 1, len(T_list)):
            set_i = T_list[i]
            set_j = T_list[j]
            intersection = len(set_i.intersection(set_j))
            if intersection > 1:
                print(f"FAIL (b): Sets {T_list[i]} and {T_list[j]} intersect in {intersection} elements.")
                return False

    # Constraint (c): Each element of S_m is contained in exactly two elements of T
    coverage = {element: 0 for element in S_m}
    for t in T:
        for element in t:
            if element in coverage:
                coverage[element] += 1
            else:
                # Should not happen if check (a) passed, but good safeguard
                print(f"FAIL (c) setup: Element {element} not in S_m mapping.")
                return False

    for element, count in coverage.items():
        if count != 2:
            print(f"FAIL (c): Element {element} is covered {count} times, expected 2.")
            return False

    return True

